<?php
namespace App\Http\Controllers\Platform;use App\Http\Controllers\Controller;use App\Models\Landlord\PlatformSupportCase;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class PlatformSupportCaseController extends Controller {public function index():View{return view('platform.support.index',['cases'=>PlatformSupportCase::query()->with('tenant')->latest('forwarded_at')->get()]);}public function update(Request $request,PlatformSupportCase $case):RedirectResponse{$data=$request->validate(['status'=>['required','in:forwarded,under_review,planned,in_progress,released,declined']]);$case->update($data);return back()->with('status','Platform case updated.');}}
